import sqlite3
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE orders(id INTEGER PRIMARY KEY, customer_id INT, total INT);
CREATE INDEX ix_cust ON orders(customer_id);
INSERT INTO customers VALUES (1,'Ana'),(2,'Bo'),(3,'Cat');
INSERT INTO orders VALUES (10,1,50),(11,1,70),(12,3,20);
""")
q_in = "SELECT name FROM customers WHERE id IN (SELECT customer_id FROM orders)"
q_ex = """SELECT name FROM customers c
         WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id)"""
q_jn = """SELECT DISTINCT c.name FROM customers c
         JOIN orders o ON o.customer_id = c.id"""
for label, q in (("IN", q_in), ("EXISTS", q_ex), ("JOIN+DISTINCT", q_jn)):
    rows = sorted(r[0] for r in db.execute(q))
    print(label, "->", rows)      # same answer from all three
    for r in db.execute("EXPLAIN QUERY PLAN " + q):
        print("    plan:", r[3])  # compare the plans yourself

import sqlite3
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE cust(id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE ord(id INTEGER PRIMARY KEY, cust_id INT, status TEXT);
CREATE TABLE item(ord_id INT, qty INT);
CREATE INDEX ix_ord ON ord(cust_id);
INSERT INTO cust VALUES (1,'Ana'),(2,'Bo'),(3,'Cat');
INSERT INTO ord VALUES (10,1,'paid'),(11,1,'paid'),(12,3,'cancelled');
INSERT INTO item VALUES (10,2),(10,1),(11,4),(12,9);
""")
slow = """SELECT name,
  (SELECT COUNT(*) FROM ord o WHERE o.cust_id = c.id) AS orders,
  (SELECT COALESCE(SUM(i.qty),0) FROM ord o JOIN item i ON i.ord_id = o.id
     WHERE o.cust_id = c.id) AS units
  FROM cust c ORDER BY id"""
fast = """WITH agg AS (
  SELECT o.cust_id, COUNT(DISTINCT o.id) AS orders, SUM(i.qty) AS units
  FROM ord o JOIN item i ON i.ord_id = o.id GROUP BY o.cust_id)
  SELECT c.name, COALESCE(a.orders,0), COALESCE(a.units,0)   -- zero for customers without rows
  FROM cust c LEFT JOIN agg a ON a.cust_id = c.id ORDER BY c.id"""
print("subqueries:", db.execute(slow).fetchall())
print("one group :", db.execute(fast).fetchall())
for r in db.execute("EXPLAIN QUERY PLAN " + slow):
    print("  slow plan:", r[3])

import sqlite3
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE products(id INTEGER PRIMARY KEY, category TEXT);
CREATE TABLE orders(id INTEGER PRIMARY KEY, customer_id INT);
CREATE TABLE order_items(order_id INT, product_id INT);
INSERT INTO customers VALUES (1,'Ana'),(2,'Bo'),(3,'Cat');
INSERT INTO products VALUES (1,'Electronics'),(2,'Electronics'),(3,'Books');
INSERT INTO orders VALUES (10,1),(11,1),(12,2),(13,3);
INSERT INTO order_items VALUES (10,1),(11,2),(12,1),(13,3);
""")
def division(cat):
    return [r[0] for r in db.execute("""
      SELECT c.name FROM customers c WHERE NOT EXISTS (
        SELECT 1 FROM products p WHERE p.category = ? AND NOT EXISTS (
          SELECT 1 FROM orders o JOIN order_items oi ON oi.order_id = o.id
          WHERE o.customer_id = c.id AND oi.product_id = p.id))""", (cat,))]
def counting(cat):
    return [r[0] for r in db.execute("""
      SELECT c.name FROM customers c JOIN orders o ON o.customer_id = c.id
      JOIN order_items oi ON oi.order_id = o.id JOIN products p ON p.id = oi.product_id
      WHERE p.category = ? GROUP BY c.id HAVING COUNT(DISTINCT p.id) =
        (SELECT COUNT(*) FROM products WHERE category = ?)""", (cat, cat))]
print("double NOT EXISTS:", division("Electronics"))
print("counting         :", counting("Electronics"))
print("empty category (vacuous truth):", division("Toys"))
